async function mockApi(path, options) {
  options = options || {};
  var user = null;
  try { user = JSON.parse(localStorage.getItem('apiqris_user')); } catch(e){}
  var invoices = [];
  try { invoices = JSON.parse(localStorage.getItem('apiqris_invoices') || '[]'); } catch(e){}
  if (!invoices || !invoices.length) {
    invoices = [
      { id: "INV-1024", order_id: "ORD-9901", amount: 50000, total_amount: 50125, status: "paid", customer_name: "Budi Santoso", customer_phone: "081298765432", created_at: new Date(Date.now() - 3600000).toISOString(), paid_at: new Date(Date.now() - 1800000).toISOString(), source: "dashboard", description: "Pembayaran Paket Pro" },
      { id: "INV-1025", order_id: "ORD-9902", amount: 125000, total_amount: 125210, status: "paid", customer_name: "Siti Rahma", customer_phone: "085712345678", created_at: new Date(Date.now() - 7200000).toISOString(), paid_at: new Date(Date.now() - 5400000).toISOString(), source: "dashboard", description: "Langganan Bulanan" },
      { id: "INV-1026", order_id: "ORD-9903", amount: 75000, total_amount: 75089, status: "pending", customer_name: "Ahmad Dani", customer_phone: "087812345678", created_at: new Date().toISOString(), source: "dashboard", description: "Pesanan Produk #4" }
    ];
    try { localStorage.setItem('apiqris_invoices', JSON.stringify(invoices)); } catch(e){}
  }

  var cleanPath = (path || '').split('?')[0];
  var body = {};
  try {
    body = (typeof options.body === 'string') ? JSON.parse(options.body || '{}') : (options.body || {});
  } catch(e) { body = {}; }

  if (cleanPath === '/api/public/config') {
    return { registration_open: true, instance_label: "APIQris Demo" };
  }
  if (cleanPath === '/api/auth/me') {
    if (!user) {
      var err = new vb("Sesi belum login.", "UNAUTHORIZED", 401);
      err.status = 401;
      throw err;
    }
    return user;
  }
  if (cleanPath === '/api/auth/login') {
    var email = body.email || "demo@apiqris.com";
    user = {
      id: 1,
      name: email === "demo@apiqris.com" ? "Merchant Demo" : (email.split('@')[0]),
      email: email,
      business_name: "Toko Demo QRIS",
      phone: "08123456789",
      role: "merchant",
      api_key: "aq_live_demo1234567890abcdef",
      created_at: new Date().toISOString()
    };
    try { localStorage.setItem('apiqris_user', JSON.stringify(user)); } catch(e){}
    return user;
  }
  if (cleanPath === '/api/auth/register') {
    user = {
      id: Date.now(),
      name: body.name || "Merchant Baru",
      email: body.email || "demo@apiqris.com",
      business_name: body.business_name || "Toko QRIS Baru",
      phone: body.phone || "08123456789",
      role: "merchant",
      api_key: "aq_live_" + Math.random().toString(36).substring(2, 12),
      created_at: new Date().toISOString()
    };
    try { localStorage.setItem('apiqris_user', JSON.stringify(user)); } catch(e){}
    return user;
  }
  if (cleanPath === '/api/auth/logout') {
    try { localStorage.removeItem('apiqris_user'); } catch(e){}
    return { success: true };
  }
  if (cleanPath === '/api/setup') {
    return { complete: true, mode: "live", step: "done", qris_uploaded: true, webhook_configured: true };
  }
  if (cleanPath === '/api/merchants') {
    return [{ id: 1, name: (user ? user.business_name : "Toko Utama"), is_default: true }];
  }
  if (cleanPath === '/api/qris-accounts') {
    return [{ id: 1, name: "QRIS Dinamis Toko", is_active: true, qris_string: "00020101021226...5802ID5914Toko Demo6007JAKARTA6304ABCD" }];
  }
  if (cleanPath === '/api/invoices') {
    if (options.method === 'POST') {
      var newInv = {
        id: "INV-" + (1020 + invoices.length + 1),
        order_id: body.order_id || ("ORD-" + Date.now().toString().slice(-4)),
        amount: Number(body.amount) || 10000,
        total_amount: (Number(body.amount) || 10000) + Math.floor(Math.random() * 500),
        status: "pending",
        customer_name: body.customer_name || "Pelanggan",
        customer_phone: body.customer_phone || "",
        description: body.description || "Pembayaran QRIS",
        created_at: new Date().toISOString(),
        qr_image_url: "/apiqris/icon-512.png",
        qr_string: "00020101021226...5802ID5914Toko Demo6007JAKARTA6304ABCD",
        source: "dashboard"
      };
      invoices.unshift(newInv);
      try { localStorage.setItem('apiqris_invoices', JSON.stringify(invoices)); } catch(e){}
      return newInv;
    }
    return {
      items: invoices,
      total: invoices.length,
      summary: {
        total_amount: invoices.filter(function(x){ return x.status === 'paid'; }).reduce(function(a, b){ return a + (b.amount || 0); }, 0),
        paid_count: invoices.filter(function(x){ return x.status === 'paid'; }).length,
        pending_count: invoices.filter(function(x){ return x.status === 'pending'; }).length
      }
    };
  }
  if (cleanPath.indexOf('/api/invoices/') === 0) {
    var invId = cleanPath.split('/')[3];
    var inv = invoices.find(function(x){ return x.id === invId; }) || invoices[0];
    return { invoice: inv };
  }
  if (cleanPath === '/api/fee-plan') {
    return { plan: "free", fee_rate: 0, monthly_fee: 0 };
  }
  if (cleanPath === '/api/ledger') {
    return {
      balance: invoices.filter(function(x){ return x.status === 'paid'; }).reduce(function(a, b){ return a + (b.amount || 0); }, 0),
      items: invoices.filter(function(x){ return x.status === 'paid'; })
    };
  }
  if (cleanPath.indexOf('/api/account') === 0) {
    return {
      api_key: (user && user.api_key) || "aq_live_demo1234567890abcdef",
      client_secret: "sec_live_998877665544332211"
    };
  }
  return {};
}

